CREATE FUNCTION [dbo].[R5REP_REPGETEXCHRATE]( 
  @rcurr	nvarchar(3),      -- reporting currency
  @curr     nvarchar(3),      -- currency
  @org		nvarchar(15) )     -- organization
RETURNS numeric(24,12) 
AS
BEGIN
  DECLARE	@repcurr nvarchar(3),
			@orgcurr nvarchar(3), 
			@exch	 numeric(24,12);

  IF COALESCE( @rcurr, '%' ) = '%'
	BEGIN
		/* If no reporting currency defined, use default currency. */
		SET @repcurr = dbo.O7DFLT2( 'DEFCURR' );
    END
  ELSE
    SET @repcurr = @rcurr;

  IF @curr IS NULL
	BEGIN
		/* Get currency from provided org. */
		SELECT TOP 1 @orgcurr = org_curr
		FROM   r5organization
		WHERE  org_code = @org;
    END
  ELSE
    SET @orgcurr = @curr;

  IF @repcurr = @orgcurr
    SET @exch = 1;
  ELSE
	BEGIN
		/* Get current exchange rate. */
		SELECT TOP 1 @exch = crr_exch
		FROM   r5exchrates
		WHERE  crr_curr    = @repcurr
		AND    crr_orgcurr = @orgcurr
		AND			SUBSTRING( CONVERT( varchar(30), getDate(), 120 ), 1, 10 ) 
			BETWEEN SUBSTRING( CONVERT( varchar(30), crr_start, 120 ), 1, 10 )
			AND		SUBSTRING( CONVERT( varchar(30), crr_end,	120 ), 1, 10 );
    END

    IF @@ERROR <> 0
		RETURN 1;

  RETURN @exch;
END
