CREATE function REPDATEADD(@date_part CHAR(4), @value_add FLOAT, @date_value DATETIME)
RETURNS DATETIME AS
BEGIN
	DECLARE @dresult DATETIME

	if (lower(@date_part) = 'dd') OR (lower(@date_part) = 'd')
		select @dresult = dateadd(dd,@value_add,@date_value)
	else if (lower(@date_part) = 'mm') OR (lower(@date_part) = 'm')
		select @dresult = dbo.O7ADD_MONTHS( @date_value, @value_add)
	else if (lower(@date_part) = 'yy') OR (lower(@date_part) = 'yyyy')
		select @dresult = dbo.O7ADD_MONTHS( @date_value, @value_add * 12)
	else if (lower(@date_part) = 'qq') OR (lower(@date_part) = 'q')
		select @dresult = dbo.O7ADD_MONTHS( @date_value, @value_add * 3)
	else if (lower(@date_part) = 'wk') OR (lower(@date_part) = 'ww')
		select @dresult = dateadd(ww,@value_add,@date_value)
	else if (lower(@date_part) = 'hh')
		select @dresult = dateadd(hh,@value_add,@date_value)
	else if (lower(@date_part) = 'mi') OR (lower(@date_part) = 'n')
		select @dresult = dateadd(mi,@value_add,@date_value)
	else if (lower(@date_part) = 'ss') OR (lower(@date_part) = 's')
		select @dresult = dateadd(ss,@value_add,@date_value)
	else if (lower(@date_part) = 'ms')
		select @dresult = dateadd(ms,@value_add,@date_value)
	else
		select @dresult = null
	return(@dresult)
END
