CREATE function REPDATEDIFF(@date_part CHAR(4),
							@start_date DATETIME,
							@end_date DATETIME)
RETURNS INT AS

BEGIN
	DECLARE @dresult INT

	if (lower(@date_part) = 'dd') OR (lower(@date_part) = 'd')
		select @dresult = datediff(dd,@start_date,@end_date)
	else if (lower(@date_part) = 'mm') OR (lower(@date_part) = 'm')
		select @dresult = datediff(mm,@start_date,@end_date)
	else if (lower(@date_part) = 'yy') OR (lower(@date_part) = 'yyyy')
		select @dresult = datediff(yyyy,@start_date,@end_date)
	else if (lower(@date_part) = 'qq') OR (lower(@date_part) = 'q')
		select @dresult = datediff(qq,@start_date,@end_date)
	else if (lower(@date_part) = 'wk') OR (lower(@date_part) = 'ww')
		select @dresult = datediff(ww,@start_date,@end_date)
	else if (lower(@date_part) = 'hh')
		select @dresult = datediff(hh,@start_date,@end_date)
	else if (lower(@date_part) = 'mi') OR (lower(@date_part) = 'n')
		select @dresult = datediff(mi,@start_date,@end_date)
	else if (lower(@date_part) = 'ss') OR (lower(@date_part) = 's')
		select @dresult = datediff(ss,@start_date,@end_date)
	else if (lower(@date_part) = 'ms')
		select @dresult = datediff(ms,@start_date,@end_date)
	else
		select @dresult = 0
	return(@dresult)
END
