CREATE FUNCTION REPDECIMALTOFRACTION( 
    @numval NUMERIC( 24, 6 ), 
    @report NVARCHAR( 6 ), 
    @usr NVARCHAR( 255 ), 
	@org NVARCHAR( 30 )	 )
RETURNS NVARCHAR( 4000 ) AS
BEGIN
   DECLARE @fractsign VARCHAR( 1 );
   DECLARE @fractinteger INTEGER;
   DECLARE @fractdecimal NUMERIC( 24, 6 );
   DECLARE @multiplier10x INTEGER;
   DECLARE @fractdenominator INTEGER;
   DECLARE @fractnumerator INTEGER;
   DECLARE @gcd INTEGER;

   IF @numval IS NULL OR ( @numval  % 1 ) = 0 RETURN DBO.REPFMTWHOLENUMLOCALE( @usr, @org, @numval )
   IF SIGN( @numval ) = -1 SET @fractsign = '-'

   SET @fractinteger = CAST( ABS( @numval ) AS INTEGER )
   SET @fractdecimal = ( ABS( @numval ) % 1 )
   SET @multiplier10x = POWER( 10, LEN( @fractdecimal ) - 2 )
   SET @gcd = DBO.REPGCD( @multiplier10x * @fractdecimal, @multiplier10x )
   SET @fractdenominator = @multiplier10x / @gcd
   SET @fractnumerator = ( @multiplier10x * @fractdecimal ) / @gcd

   IF @report = 'WZJSIR' AND COALESCE( @fractdenominator, 0 ) NOT IN ( 2, 4, 8, 16 )
      RETURN DBO.REPFMTNUMLOCALE( @usr, @org, @numval )
   ELSE
      RETURN RTRIM( LTRIM( COALESCE( @fractsign, '' ) + 
                           COALESCE( DBO.REPFMTWHOLENUMLOCALE( @usr, @org, ( CASE WHEN @fractinteger <> 0 THEN @fractinteger END ) ), '' ) + 
                           CASE WHEN @fractinteger <> 0 THEN ' ' ELSE '' END +
                           COALESCE( CONVERT( VARCHAR, @fractnumerator ), '' ) + '/' + COALESCE( CONVERT( VARCHAR,  @fractdenominator ), '' ) ) )
   RETURN NULL
END
