create function  REPGETSUBTITLE   (@P_R5FUNC    NVARCHAR(6),
                                   @P_R5LANG    NVARCHAR(2),
                                   @P_R5USER    NVARCHAR(255),
                                   @P_AFTER     INTEGER,
                                   @P_BEFORE    INTEGER,
                                   @P_BETWEEN   INTEGER,
                                   @P_SEL_START NVARCHAR(10),
                                   @P_SEL_END   NVARCHAR(10)
                                   )
returns nvarchar(255)
AS
BEGIN
    DECLARE @V_SUBTITLE NVARCHAR(255) 

    SET @V_SUBTITLE = N''

       SELECT @V_SUBTITLE = REPLACE(REPLACE(BOT_TEXT,':PARAM1',dbo.REPPARAMDATE(@P_R5USER,@P_SEL_START)),':PARAM2',dbo.REPPARAMDATE(@P_R5USER,@P_SEL_END))
       FROM R5BOILERTEXTS
       WHERE BOT_NUMBER = CASE WHEN (@P_SEL_START <> N'%' AND @P_SEL_END <> N'%') THEN @P_BETWEEN
                               WHEN (@P_SEL_START <> N'%') THEN @P_AFTER
                               WHEN (@P_SEL_END <> N'%') THEN @P_BEFORE END
              AND   BOT_FUNCTION = @P_R5FUNC
              AND   BOT_LANG     = @P_R5LANG

                If @@ROWCOUNT = 0
                   SET @V_SUBTITLE = N''


RETURN @V_SUBTITLE
END
